from dataclasses import dataclass

@dataclass
class GameField:
    matrix: list[list[int]]

    def __post_init__(self):
        if len(self.matrix) != 3:
            raise ValueError("Field must be 3x3")
        if any(len(row) != 3 for row in self.matrix):
            raise ValueError("Field must be 3x3")
        for row in self.matrix:
            for cell in row:
                if cell not in (0, 1, 2):
                    raise ValueError("Cell values must be 0, 1 or 2")

changes = 0
for r in range(3):
    for c in range(3):
        if old[r][c] != new[r][c]:
            if old[r][c] != 0 or new[r][c] != expected_symbol:
                raise InvalidMoveError(f"Invalid change at ({r},{c})")
            changes += 1
if changes != 1:
    raise InvalidMoveError("Exactly one move required")

def winner(f):
    lines = [row[:] for row in f]
    lines += [[f[0][c], f[1][c], f[2][c]] for c in range(3)]
    lines.append([f[0][0], f[1][1], f[2][2]])
    lines.append([f[0][2], f[1][1], f[2][0]])
    for line in lines:
        if line[0] != 0 and len(set(line)) == 1:
            return line[0]
    return 0

def minimax(f, depth, is_max):
    w = winner(f)
    if w == 2:
        return 10 - depth
    if w == 1:
        return -10 + depth
    empty = [(r, c) for r in range(3) for c in range(3) if f[r][c] == 0]
    if not empty:
        return 0
    scores = []
    for r, c in empty:
        f2 = [row[:] for row in f]
        f2[r][c] = 2 if is_max else 1
        scores.append(minimax(f2, depth + 1, not is_max))
    return max(scores) if is_max else min(scores)

def best_move(f):
    best_score, best = -float("inf"), None
    for r in range(3):
        for c in range(3):
            if f[r][c] == 0:
                f2 = [row[:] for row in f]
                f2[r][c] = 2
                score = minimax(f2, 0, False)
                if score > best_score:
                    best_score, best = score, (r, c)
    return best
